import base64
import json
from pathlib import Path

ICON_192 = ''''''

ICON_512 = ''''''

manifest_path = Path('public/manifest.webmanifest')
manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
manifest['icons'] = [
    {
        'src': '/leafpdf-icon-192.png',
        'sizes': '192x192',
        'type': 'image/png',
        'purpose': 'any',
    },
    {
        'src': '/leafpdf-icon-512.png',
        'sizes': '512x512',
        'type': 'image/png',
        'purpose': 'any maskable',
    },
    {
        'src': '/leafpdf-icon.svg',
        'sizes': 'any',
        'type': 'image/svg+xml',
        'purpose': 'any',
    },
]
manifest_path.write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
Path('public/leafpdf-icon-192.png').write_bytes(base64.b64decode(ICON_192))
Path('public/leafpdf-icon-512.png').write_bytes(base64.b64decode(ICON_512))
